CASE
WHEN length(regexp_extract(_udf_param_0, '(?iu)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(The|An|A)?[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(parent|father|mother|patient|beneficiary|enrollee|member|provider)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*[^.]*(requested|required|asked|requires|reimbursement|coverage|requesting|has)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*[^.]*(of|for|medication|reimbursement|coverage|services)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?)\\.', 5)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(The|An|A)?[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(parent|father|mother|patient|beneficiary|enrollee|member|provider)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*[^.]*(requested|required|asked|requires|reimbursement|coverage|requesting|has)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*[^.]*(of|for|medication|reimbursement|coverage|services)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?)\\.', 5)
WHEN length(regexp_extract(_udf_param_0, '(?iu)At issue[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(in this case|)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(is|)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(whether|if)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?) (is|were|was) medically (necessary|indicated)', 4)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)At issue[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(in this case|)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(is|)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*(whether|if)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?) (is|were|was) medically (necessary|indicated)', 4)
WHEN length(regexp_extract(_udf_param_0, '(?iu)the requested (medication|treatment|service|procedure)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?) (is|were|was) (likely to be|medically necessary|medically indicated)', 2)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)the requested (medication|treatment|service|procedure)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?) (is|were|was) (likely to be|medically necessary|medically indicated)', 2)
WHEN length(regexp_extract(_udf_param_0, '(?iu)patients provider has prescribed the medication[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+([^.]+?)[^\\n]', 1)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)patients provider has prescribed the medication[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+([^.]+?)[^\\n]', 1)
WHEN length(regexp_extract(_udf_param_0, '(?iu)(wishes|desires|like) to (undergo|take)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+([^.]+?)[^\\n]', 3)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)(wishes|desires|like) to (undergo|take)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+([^.]+?)[^\\n]', 3)
WHEN length(regexp_extract(_udf_param_0, '(?iu)The (Health Plan|Plan|Insurance Company) (determined the|determined|indicates) ([^\\n]+?) (is|was|were) not', 3)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)The (Health Plan|Plan|Insurance Company) (determined the|determined|indicates) ([^\\n]+?) (is|was|were) not', 3)
WHEN length(regexp_extract(_udf_param_0, '(?iu)treatment[^.]*with[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+([^.]+?) (is|were|was)', 1)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)treatment[^.]*with[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+([^.]+?) (is|were|was)', 1)
WHEN length(regexp_extract(_udf_param_0, '(?iu)(requested|required|asked|requires|reimbursement|coverage|request|requesting)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*[^.]*(for|medication|reimbursement|coverage|of)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?)\\.', 3)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)(requested|required|asked|requires|reimbursement|coverage|request|requesting)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]*[^.]*(for|medication|reimbursement|coverage|of)[ \\t\\n\\x0B\\f\\r\\x1C-\\x1F\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000]+(\\p{Nd}*[\\p{L}\\p{N}_]+[^\\n]+?)\\.', 3)
WHEN _udf_param_0 RLIKE '(?iu)is seeking () for ([^.]+)' THEN CAST(NULL AS STRING)
WHEN length(regexp_extract(_udf_param_0, '(?iu)physicians recommended ([^.]+)', 1)) > 2
THEN regexp_extract(_udf_param_0, '(?iu)physicians recommended ([^.]+)', 1)
WHEN _udf_param_1 <> '' AND _udf_param_1 <> 'Other' AND _udf_param_2 <> '' AND _udf_param_2 <> 'Other' THEN concat(_udf_param_1, _udf_param_2)
ELSE CAST(NULL AS STRING)
END
